// ===== MCP Server：定义并暴露工具 =====
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";

const server = new Server(
  { name: "my-mcp-server", version: "1.0.0" },
  { capabilities: { tools: {} } }
);

// 声明 Server 暴露哪些工具
server.setRequestHandler("tools/list", async () => ({
  tools: [
    {
      name: "get_weather",
      description: "获取指定城市的天气信息，返回温度、湿度和天气状况",
      inputSchema: {
        type: "object",
        properties: {
          city: { type: "string", description: "城市名称" }
        },
        required: ["city"]
      }
    }
  ]
}));

// 处理工具调用请求
server.setRequestHandler("tools/call", async (request) => {
  const { name, arguments: args } = request.params;
  if (name === "get_weather") {
    // 生产环境：此处应有参数校验、鉴权、限流、审计
    const weather = await fetchWeather(args.city);
    return { content: [{ type: "text", text: JSON.stringify(weather) }] };
  }
  throw new Error(`Unknown tool: ${name}`);
});

const transport = new StdioServerTransport();
await server.connect(transport);

// ===== Agent ReAct 循环 =====
async function reactAgent(query: string, maxRounds = 10) {
  const messages: Message[] = [{ role: "user", content: query }];
  for (let round = 0; round < maxRounds; round++) {
    const response = await llm.chat(messages, tools);
    if (response.tool_calls) {
      // 执行工具调用（本地函数或通过 MCP Client 调 MCP Server）
      const result = await executeTool(response.tool_calls[0]);
      messages.push({ role: "tool", content: result });
    } else {
      return response.content; // 模型决定直接回答，循环结束
    }
  }
  throw new Error("Agent exceeded max rounds"); // 终止条件
}
